package merge

import (
	"bytes"
	"path"
	"strings"
	"unicode/utf8"
)

// lockfiles are regenerated by a tool, never merged by hand: a merged
// lockfile reads fine and installs something nobody asked for.
var lockfiles = map[string]bool{
	"go.sum": true, "package-lock.json": true, "npm-shrinkwrap.json": true, "yarn.lock": true,
	"pnpm-lock.yaml": true, "Cargo.lock": true, "poetry.lock": true, "composer.lock": true,
	"Gemfile.lock": true, "Pipfile.lock": true, "uv.lock": true, "gradle.lockfile": true,
	"packages.lock.json": true, "mix.lock": true, "pubspec.lock": true, "Podfile.lock": true,
	"flake.lock": true, "bun.lockb": true,
}

// generatedMarker is Go's convention for a generated file, also used
// elsewhere; looked for in the head only.
var generatedMarker = []byte("DO NOT EDIT")

// Excluded says why a both-changed file is no simple merge whatever its
// lines: a lockfile, a minified or generated file, or not UTF-8 text. ""
// when it may be merged. Every version merged is passed: any one binary or
// generated version rules it out.
func Excluded(p string, versions ...[]byte) string {
	base := path.Base(p)
	switch {
	case lockfiles[base] || strings.HasSuffix(base, ".lock"):
		return "lockfile"
	case strings.Contains(base, ".min."):
		return "generated"
	}
	for _, v := range versions {
		if bytes.IndexByte(v, 0) >= 0 || !utf8.Valid(v) {
			return "binary"
		}
		head := v[:min(len(v), 1024)]
		if bytes.Contains(head, generatedMarker) {
			return "generated"
		}
	}
	return ""
}
